(function(){'use strict';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n/100);let catalogue,selected,order,receipt,busy=false;
async function api(path,data){const r=await fetch('/api/shop/'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(20000)});let d;try{d=await r.json()}catch{throw Error('The service is temporarily unavailable. No real payment has been taken.');}if(!r.ok)throw Error(d.error||'The test request could not be completed.');return d;}
function status(s,error=false){$('shop-status').textContent=s;$('shop-status').className=error?'error':'status';}
async function run(fn){if(busy)return;busy=true;for(const b of document.querySelectorAll('button'))b.disabled=true;try{await fn()}catch(e){status(e.message,true)}finally{busy=false;for(const b of document.querySelectorAll('button'))b.disabled=false;}}
function complete(d){receipt=d;$('shop-order').hidden=true;$('order-review').hidden=true;$('order-complete').hidden=false;$('complete-summary').textContent=(d.orderId?'Test reference '+d.orderId+'. ':'')+'Temporary test access is confirmed for '+selected.name+'.';$('product-delivery').href=d.delivery;$('product-delivery').textContent=selected.kind==='download'?'Download the checklist PDF':'Open your advanced guide';status('Test access ready. No real payment was taken.');}
$('shop-order').onsubmit=e=>{e.preventDefault();run(async()=>{if(!$('shop-consent').checked)throw Error('Confirm test mode before continuing.');order=await api('order',{product:selected.id,testConsent:true,termsVersion:catalogue.termsVersion});$('shop-order').hidden=true;$('order-review').hidden=false;$('order-summary').innerHTML='<p><strong>'+esc(order.name)+'</strong></p><p>Catalogue price: '+money(order.catalogueAmount)+'</p><p><strong>Due now: ₹0 · simulation only</strong></p><p class="small">No real access plan, payment or invoice is activated.</p>';$('order-title').tabIndex=-1;$('order-title').focus();});};
$('order-confirm').onclick=()=>run(async()=>{if(!order)throw Error('Start test checkout again.');complete(await api('confirm',{orderId:order.orderId,testConsent:true}));});
$('order-cancel').onclick=()=>{order=null;$('order-review').hidden=true;$('shop-order').hidden=false;status('Test order cancelled in this screen. No money was taken.');};
$('save-test-receipt').onclick=()=>{if(!receipt)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}));a.href=url;a.download='Navigator-Test-Order-'+selected.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);};
(async()=>{try{catalogue=await api('catalogue');const id=new URLSearchParams(location.search).get('product')||'checklist';$('product-tabs').innerHTML=catalogue.products.map(p=>'<a href="/shop.html?product='+esc(p.id)+'" '+(p.id===id?'aria-current="page"':'')+'>'+esc(p.name)+'</a>').join('');selected=catalogue.products.find(p=>p.id===id);if(!selected)throw Error('This product is unavailable. Choose one of the listed products above.');$('product-detail').innerHTML='<p class="kicker">'+(selected.kind==='download'?'Printable download':'Advanced self-service guide')+'</p><h2>'+esc(selected.name)+'</h2><p class="price">'+money(selected.amount)+'</p><p class="small">Catalogue price · '+(selected.kind==='guide'?'90-day single-account access':'one organisation, this edition')+' · ₹0 charged in this test</p><p>'+esc(selected.scope)+'</p><h3>What you receive</h3><ul>'+selected.includes.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul><details><summary>What is outside this product</summary><ul>'+selected.excludes.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul></details><p class="small">Edition '+esc(selected.edition)+'</p>'+(selected.sample?'<a class="button" href="'+esc(selected.sample)+'" target="_blank" rel="noopener">Preview the sample PDF</a>':'<a href="'+(selected.id==='aggrieved'?'/#woman':'/#respondent')+'">Use the free guidance first</a>');$('product-licence').textContent=selected.licence;$('shop-content').hidden=false;const session=await api('session?product='+id);if(session.hasTestAccess)complete(session);else if(session.signedIn){$('shop-order').hidden=false;status('Review the scope, then start test checkout.');}else{$('shop-signin').hidden=false;$('shop-signin-link').href='/account?product='+id;status('Choose your product, then sign in for test checkout.');}}catch(e){status(e.message,true);}})();
})();
